export function journalAppendAddress(
  root,
  action,
  at,
  options = {},
) {
  return dataArtifactAddress({
    root,
    ...(options.rootName === undefined ? {} : { rootName: options.rootName }),
    tier: "log",
    encoding: options.encoding ?? "jsonl",
    at,
    action,
    subject: options.subject ?? action,
  });
}

